import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { Button as BaseUIButton } from "@base-ui/react/button";
import { cn } from "../../lib/utils";
import { Spinner } from "../spinner/spinner";

const buttonVariants = cva(
  "inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-md text-sm font-medium ring-offset-background transition-colors focus-visible:outline-hidden focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0 cursor-pointer",
  {
    variants: {
      variant: {
        default:
          "bg-primary text-primary-foreground hover:bg-primary-hover",
        destructive:
          "bg-destructive text-destructive-foreground hover:bg-destructive-hover",
        outline:
          "border border-input bg-background text-foreground hover:bg-accent hover:text-accent-foreground",
        secondary:
          "bg-secondary text-secondary-foreground hover:bg-secondary-hover",
        ghost: "hover:bg-secondary hover:text-secondary-foreground",
        link: "text-primary underline-offset-4 hover:underline",
        "link-muted": "text-foreground underline-offset-4 hover:underline hover:text-muted-foreground",
      },
      size: {
        sm: "h-6 px-3 py-1 text-12 leading-tight rounded font-normal", // 24px, 12px font, 1.2 line-height, 4px radius
        default: "h-8 px-3 py-0.5 text-13 leading-snug rounded-lg font-medium", // 32px, 13px font, 1.3 line-height, 8px radius
        icon: "h-8 w-8 rounded-lg", // 32px square, 8px radius
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
);

export interface ButtonProps
  extends Omit<React.ComponentPropsWithoutRef<typeof BaseUIButton>, 'render'>,
  VariantProps<typeof buttonVariants> {
  /**
   * The visual style of the button.
   * @default "default"
   */
  variant?:
    | "default"
    | "destructive"
    | "outline"
    | "secondary"
    | "ghost"
    | "link"
    | "link-muted";
  /**
   * The size of the button.
   * @default "default"
   */
  size?: "sm" | "default" | "icon";
  /**
   * Render the button as a different element (e.g. an anchor tag)
   * @example <Button render={<a href="/" />}>Link</Button>
   */
  render?: React.ReactElement;
  /**
   * If true, the button will show a spinner and be disabled
   */
  loading?: boolean;
}

/**
 * Button component with multiple variants and sizes
 * Optimized for plugin UIs with compact sizing
 *
 * @example
 * ```tsx
 * <Button variant="default">
 *   Click me
 * </Button>
 *
 * <Button variant="destructive" size="sm">
 *   Delete
 * </Button>
 *
 * <Button render={<a href="/link" />}>Link Button</Button>
 * ```
 */
const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, render, loading = false, disabled, children, ...props }, ref) => {
    return (
      <BaseUIButton
        ref={ref}
        className={cn(buttonVariants({ variant, size, className }))}
        disabled={loading || disabled}
        render={render}
        {...props}
      >
        {render ? (
          children
        ) : (
          <>
            {loading && <Spinner size="xs" className="mr-1 text-current" />}
            {children}
          </>
        )}
      </BaseUIButton>
    );
  }
);
Button.displayName = "Button";

export { Button, buttonVariants };
