import * as React from "react";
import { Slider as SliderPrimitive } from "@base-ui/react/slider";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../../lib/utils";

const sliderVariants = cva(
  "relative flex touch-none select-none",
  {
    variants: {
      variant: {
        default: "",
        error: "",
      },
      orientation: {
        horizontal: "w-full items-center cursor-ew-resize",
        vertical: "items-center flex-col cursor-ns-resize",
      },
    },
    defaultVariants: {
      variant: "default",
      orientation: "horizontal",
    },
  }
);

const trackVariants = cva(
  "relative grow overflow-hidden rounded-full",
  {
    variants: {
      variant: {
        default: "bg-secondary",
        error: "bg-[color-mix(in_srgb,var(--destructive)_20%,transparent)]",
      },
      orientation: {
        horizontal: "h-1 w-full",
        vertical: "w-1 h-full",
      },
    },
    defaultVariants: {
      variant: "default",
      orientation: "horizontal",
    },
  }
);

const rangeVariants = cva("absolute", {
  variants: {
    variant: {
      default: "bg-primary",
      error: "bg-destructive",
    },
    orientation: {
      horizontal: "h-full",
      vertical: "w-full",
    },
  },
  defaultVariants: {
    variant: "default",
    orientation: "horizontal",
  },
});

const thumbVariants = cva(
  "relative block h-4 w-4 rounded-full border-2 bg-background ring-offset-background transition-[transform,box-shadow,colors] duration-150 ease-out focus-visible:outline-hidden focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50 before:absolute before:-inset-1 before:content-['']",
  {
    variants: {
      variant: {
        default:
          "border-primary hover:scale-110 hover:shadow-[0_0_0_4px_color-mix(in_srgb,var(--primary)_30%,transparent)] data-dragging:scale-110 data-dragging:shadow-[0_0_0_4px_color-mix(in_srgb,var(--primary)_30%,transparent)]",
        error:
          "border-destructive hover:scale-110 hover:shadow-[0_0_0_4px_color-mix(in_srgb,var(--destructive)_30%,transparent)] data-dragging:scale-110 data-dragging:shadow-[0_0_0_4px_color-mix(in_srgb,var(--destructive)_30%,transparent)]",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  }
);

export interface SliderProps
  extends Omit<
      React.ComponentPropsWithoutRef<typeof SliderPrimitive.Root>,
      "value" | "defaultValue" | "onValueChange" | "onValueCommitted"
    >,
    VariantProps<typeof sliderVariants> {
  /**
   * The controlled value of the slider.
   * Use a single-element array for a single value slider: [50]
   * Use a two-element array for a range slider: [20, 80]
   */
  value?: number[];

  /**
   * The default value for uncontrolled usage.
   * Use a single-element array for a single value slider: [50]
   * Use a two-element array for a range slider: [20, 80]
   */
  defaultValue?: number[];

  /**
   * Callback fired when the value changes.
   */
  onValueChange?: (value: number[]) => void;

  /**
   * Callback fired when the value is committed (on mouse/touch release).
   */
  onValueCommit?: (value: number[]) => void;

  /**
   * The minimum value of the slider.
   * @default 0
   */
  min?: number;

  /**
   * The maximum value of the slider.
   * @default 100
   */
  max?: number;

  /**
   * The step increment of the slider.
   * @default 1
   */
  step?: number;

  /**
   * The minimum number of steps between thumbs in a range slider.
   * Prevents thumbs from crossing.
   */
  minStepsBetweenThumbs?: number;

  /**
   * The orientation of the slider.
   * @default "horizontal"
   */
  orientation?: "horizontal" | "vertical";

  /**
   * Whether the slider is disabled.
   */
  disabled?: boolean;

  /**
   * The visual variant of the slider.
   * @default "default"
   */
  variant?: "default" | "error";

  /**
   * Optional aria-label for accessibility.
   * Required for screen readers. Can also be provided individually on thumbs.
   */
  "aria-label"?: string;
}

const Slider = React.forwardRef<
  HTMLDivElement,
  SliderProps
>(
  (
    {
      className,
      variant,
      value,
      defaultValue,
      onValueChange,
      onValueCommit,
      min = 0,
      max = 100,
      step = 1,
      minStepsBetweenThumbs,
      orientation = "horizontal",
      disabled,
      "aria-label": ariaLabel,
      ...props
    },
    ref
  ) => {
    // Determine number of thumbs from value or defaultValue
    const thumbCount =
      (value?.length ?? defaultValue?.length ?? 1);

    return (
      <SliderPrimitive.Root
        ref={ref}
        className={cn(sliderVariants({ variant, orientation }), className)}
        aria-invalid={variant === "error" || undefined}
        value={value}
        defaultValue={defaultValue}
        onValueChange={onValueChange ? (val: number | readonly number[]) => onValueChange(Array.isArray(val) ? [...val] : [val]) : undefined}
        onValueCommitted={onValueCommit ? (val: number | readonly number[]) => onValueCommit(Array.isArray(val) ? [...val] : [val]) : undefined}
        min={min}
        max={max}
        step={step}
        minStepsBetweenValues={minStepsBetweenThumbs}
        orientation={orientation}
        disabled={disabled}
        aria-label={ariaLabel}
        {...props}
      >
        <SliderPrimitive.Control className={cn(
          "flex",
          orientation === "horizontal" ? "w-full items-center h-5" : "h-full w-5 flex-col items-center justify-center"
        )}>
          <SliderPrimitive.Track
            className={cn(trackVariants({ variant, orientation }))}
          >
            <SliderPrimitive.Indicator
              className={cn(rangeVariants({ variant, orientation }))}
            />
          </SliderPrimitive.Track>
          {Array.from({ length: thumbCount }).map((_, i) => (
            <SliderPrimitive.Thumb
              key={i}
              className={cn(thumbVariants({ variant }))}
              aria-label={thumbCount > 1 ? `Value ${i + 1}` : ariaLabel}
            />
          ))}
        </SliderPrimitive.Control>
      </SliderPrimitive.Root>
    );
  }
);

Slider.displayName = "Slider";

export { Slider };
